  Lemma Linfr : forall ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
      y8 y9 y13 y18 y19 y20 y21 y22 y23 y24 y31
      (F : bvmap 5 word) fc (m m1 : word -> option byte) j R,
    mem_inv rsegs m1 ->
