    stk rsegs m1 (bv_unsigned sp - 80) (bv_unsigned sp + -80) ->
    rw_cells rsegs m1 (bv_unsigned sp + -80) (saved9 s8 s7 s6 s5 s4 s3 s2 s1 s0 j) ->
